"""Build the reviewed runtime Q&A pack without changing XDE's original knowledge."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1];entries={}
for filename in ['franklin-knowledge.json','franklin-knowledge-extra.json']:
 for e in json.loads((root/'dist'/filename).read_text())['entries']:
  if e['id'] in entries:
   previous=entries[e['id']];e={**e,'patterns':list(dict.fromkeys(previous.get('patterns',[])+e.get('patterns',[])))}
  entries[e['id']]={**e,'provenance':filename,'answer_policy':'existing-project-content'}
extras=[
 ('support-intake','support',['help with a problem','bantu masalah game','gta v tidak jalan'],'Tell me what you were doing, what you expected, and what happened instead. If there is an error, copy its exact wording. Your selected OS and app build provide context; they do not prove the cause.'),
 ('support-missing-detail','support',['what information do you need','data apa yang dibutuhkan','what should i send with a crash report'],'Include the device model, OS version, app build, the action immediately before the failure, and the relevant Logs files. Attach a log with the paperclip. If you do not know a detail, say so rather than guessing.'),
 ('support-how-logs','logs',['how do i attach a log','cara kirim log','upload crash log'],'Use the paperclip beside Send, choose run.log, run.prev.log, or crash-*.txt, then press Send. Describe what happened before the failure. Review the file for personal information before sharing it.'),
 ('support-log-location','logs',['where can i find the logs','dimana file log','log folder location'],'On iPhone or iPad: Files > On My iPhone/iPad > GTA V > Logs. On Mac: ~/Library/Logs/GTA5. Keep run.log, run.prev.log and crash-*.txt where available.'),
 ('support-invalid-file','logs',['my log upload was rejected','file log ditolak','unsupported file attachment'],'Choose a non-empty GTA V .log or .txt file up to 512 KB. A screenshot, ZIP, IPA or settings file is not a diagnostic log. If a valid log is rejected, describe the filename and the notification you saw.'),
 ('support-no-log','logs',['i dont have a log','tidak punya log','there is no logs folder'],'Tell me the device, selected app build, and whether the failure happens before opening the launcher, after Play, or during a mission. If you can reproduce it, check the Logs folder afterward. Without a log, I can narrow the questions but cannot confirm the cause.'),
 ('support-analyze-limits','support',['can you scan my phone','can you detect my ram','bisa scan hp saya'],'I cannot perform a live hardware, memory or temperature scan. I can use the model you provide, your selected OS/build, and values recorded in an attached log. Logged values describe that session, not the current state of the phone.'),
 ('support-build-unknown','support',['i dont know my app version','tidak tahu versi aplikasi','how do i identify my build'],'Choose “I’m not sure / another version” if needed. You can attach run.log or paste the GTA5 UUID from the beginning of the log. I will match only known prefixes in XDE’s supplied release list; an unmatched UUID stays unverified.'),
 ('support-update-recommendation','updates',['should i update','apakah harus update','which build should i install'],'Check the Updates page and the community download instructions for the current release. Tell me your installed build and the issue you want to fix. A fix mentioned in a test build is not automatically available in a public release.'),
 ('support-memory-thermal','performance',['what does critical mean','critical fair serious meaning','arti fair serious critical'],'In a log, fair, serious and critical can describe the recorded thermal state. They are not a guarantee of FPS or a complete compatibility verdict. Serious or critical heat calls for cooling and a more conservative workload. Please include the exact line so I can distinguish a thermal label from another warning.'),
 ('support-no-guaranteed-fps','performance',['can you guarantee 60 fps','pasti 60 fps','exact fps on my iphone'],'I cannot guarantee an FPS number from the device name alone. Performance also depends on the build, signing memory allowance, settings, scene and temperature. Share the device and the problem you observe, or attach a log for evidence.'),
 ('support-settings-import','settings',['generate graphics json','buatkan setting otomatis','download best settings file'],'The automatic graphics-settings generator is not offered here. You can use Check Performance to review a configuration, or ask about an individual setting. Any configuration assessment is an estimate, not a measured FPS benchmark.'),
 ('helper-device-memory','helper',['why do you remember my os','os saya tersimpan','change saved operating system'],'The OS and version you confirm are saved in this browser. A new chat asks for the app build again. Use Change, then Edit saved OS to update them, or Forget saved OS to remove the saved profile.'),
 ('helper-disconnect-memory','helper',['what does disconnect delete','disconnect hapus apa','does disconnect forget os'],'The red phone button deletes the chat session, draft, attachment and selected app build. Your confirmed OS profile remains saved in this browser until you use Forget saved OS. Swiping down only minimizes the conversation.'),
 ('helper-language','helper',['can i ask in indonesian','boleh bahasa indonesia','do you understand bahasa indonesia'],'Yes. You can describe GTA V or project issues in Indonesian or English. Keep error messages and filenames unchanged so I can match them accurately. My replies on this website are in English.'),
 ('helper-accuracy','helper',['are your answers always correct','apakah jawabanmu pasti benar','can i trust the diagnosis'],'A symptom or log-signature match is a starting point, not a confirmed diagnosis. I distinguish released fixes, test builds and unresolved issues. If the evidence is ambiguous, I should ask for details instead of selecting a cause.'),
 ('helper-knowledge','helper',['what is your knowledge based on','sumber knowledge kamu','how do you know this'],'Technical support uses the supplied XDE issue records and the project’s published pages. General GTA V answers use the local game knowledge pack. If the supplied information does not answer your question reliably, I will say what is missing.'),
 ('helper-note-links','helper',['send developer knowledge notes','download xde knowledge','open xde notes'],'I can explain the relevant support steps here, but I do not provide direct links to XDE’s knowledge notes in chat. Describe the issue or attach the log so I can use the relevant information.'),
 ('helper-scope-refusal','helper',['can you help outside gta v','can you answer other topics','bisa jawab selain gta'],'I can only help with GTA V and the GTA V iOS Project. I cannot answer unrelated questions. You can ask about the game, installation, launcher settings, compatibility or troubleshooting.'),
 ('support-mission-detail','missions',['help me with a mission','bantu misi','stuck on a mission'],'Which mission are you playing, which character are you using, and what is the current objective? Tell me whether you need gameplay guidance or the game is freezing/crashing. I can avoid story spoilers unless you ask for them.'),
 ('support-spoiler-consent','story',['no spoilers please','jangan spoiler','avoid spoilers'],'Understood. I’ll keep story details out of the guidance. Tell me the mission name and the objective you are stuck on; if the next step would reveal a plot point, I should ask before explaining it.'),
 ('support-touch-detail','controls',['a button is missing','tombol tidak muncul','touch control not working'],'Tell me the mission or menu and the exact button label the game requests. Also say whether you are on foot, in a vehicle, or using a controller. Touch layouts depend on context and app build.'),
 ('support-settings-detail','settings',['help with graphics settings','bantu setting grafik','which setting should i change'],'What do you want to improve: stutter, sustained FPS, heat, or image quality? Share the device model, app build, and current resolution/FPS cap. Change one option at a time so the effect is easier to identify.'),
 ('support-download','community',['where do i download the app','download aplikasi dimana','where is the ipa download'],'The community handles current app downloads and build-specific instructions. Use the project’s Discord link, and check the release notes before installing. I should not invent a download file or a version number.'),
]
for id,topic,patterns,answer in extras:entries[id]={'id':id,'topic':topic,'patterns':patterns,'keywords':[],'answer':answer,'provenance':'reviewed-helper-workflow','answer_policy':'clarify-or-explain-existing-workflow'}
translations={'gta-michael':['siapa michael'],'gta-trevor':['siapa trevor'],'gta-lamar':['siapa lamar'],'gta-lester':['siapa lester'],'gta-chop':['siapa chop'],'gta-setting':['gta v berlatar dimana'],'gta-overview':['apa itu gta v'],'ios-not-official':['apakah gta v ios resmi'],'ios-touch-layout':['cara edit tombol sentuh'],'ios-fps-cap':['pilih batas fps berapa'],'gta-special-abilities':['kemampuan khusus karakter'],'gta-character-switching':['cara ganti karakter'],'gta-cheats':['cara pakai cheat gta v'],'ios-signing-expired':['aplikasi tidak bisa dibuka lagi']}
for id,patterns in translations.items():
 if id in entries:entries[id]['patterns']+=patterns
output={'schema_version':1,'scope':['GTA V','GTA V iOS Project'],'policy':{'unsupported_claims':'ask-for-evidence','outside_scope':'polite-refusal','developer_records':'handled-first-by-original-XDE-matcher','not_exhaustive':True},'entries':list(entries.values())}
(root/'dist/franklin-dataset.json').write_text(json.dumps(output,indent=2,ensure_ascii=False)+'\n')
print(f"Built {len(entries)} reviewed Q&A entries; {sum(len(e['patterns']) for e in entries.values())} question patterns. Original XDE records stay separate.")
